class Solution {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        if (subRoot == null) {
            return true;
        }
        if (root == null) {
            return false;
        }
        if (same(root, subRoot)) {
            return true;
        }
        return isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot);
    }

    private boolean same(TreeNode a, TreeNode b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        return a.val == b.val && same(a.left, b.left) && same(a.right, b.right);
    }
}

import java.util.*;

class Solution {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        if (subRoot == null) {
            return true;
        }
        if (root == null) {
            return false;
        }

        Deque<TreeNode> candidates = new ArrayDeque<>();
        candidates.push(root);
        while (!candidates.isEmpty()) {
            TreeNode node = candidates.pop();
            if (sameIterative(node, subRoot)) {
                return true;
            }
            if (node.left != null) {
                candidates.push(node.left);
            }
            if (node.right != null) {
                candidates.push(node.right);
            }
        }
        return false;
    }

    private boolean sameIterative(TreeNode a, TreeNode b) {
        Deque<Pair> stack = new ArrayDeque<>();
        stack.push(new Pair(a, b));
        while (!stack.isEmpty()) {
            Pair current = stack.pop();
            TreeNode left = current.left;
            TreeNode right = current.right;
            if (left == null && right == null) {
                continue;
            }
            if (left == null || right == null || left.val != right.val) {
                return false;
            }
            stack.push(new Pair(left.left, right.left));
            stack.push(new Pair(left.right, right.right));
        }
        return true;
    }

    private static class Pair {
        TreeNode left;
        TreeNode right;

        Pair(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }
    }
}

import java.util.*;

class Solution {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        List<String> text = new ArrayList<>();
        List<String> pattern = new ArrayList<>();
        serialize(root, text);
        serialize(subRoot, pattern);
        return containsWithKmp(text, pattern);
    }

    private void serialize(TreeNode node, List<String> output) {
        if (node == null) {
            output.add("#");
            return;
        }
        output.add("V" + node.val);
        serialize(node.left, output);
        serialize(node.right, output);
    }

    private boolean containsWithKmp(List<String> text, List<String> pattern) {
        if (pattern.isEmpty()) {
            return true;
        }
        int[] lps = buildLps(pattern);
        int j = 0;
        for (int i = 0; i < text.size(); i++) {
            while (j > 0 && !pattern.get(j).equals(text.get(i))) {
                j = lps[j - 1];
            }
            if (pattern.get(j).equals(text.get(i))) {
                j++;
                if (j == pattern.size()) {
                    return true;
                }
            }
        }
        return false;
    }

    private int[] buildLps(List<String> pattern) {
        int[] lps = new int[pattern.size()];
        int length = 0;
        for (int i = 1; i < pattern.size(); i++) {
            while (length > 0 && !pattern.get(i).equals(pattern.get(length))) {
                length = lps[length - 1];
            }
            if (pattern.get(i).equals(pattern.get(length))) {
                length++;
                lps[i] = length;
            }
        }
        return lps;
    }
}

import java.util.*;

class Solution {
    private final Map<String, Integer> ids = new HashMap<>();
    private final Set<Integer> rootSubtreeIds = new HashSet<>();
    private int nextId = 1;

    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        int targetId = encode(subRoot, false);
        encode(root, true);
        return rootSubtreeIds.contains(targetId);
    }

    private int encode(TreeNode node, boolean record) {
        if (node == null) {
            return 0;
        }
        int left = encode(node.left, record);
        int right = encode(node.right, record);
        String key = node.val + "," + left + "," + right;
        int id = ids.computeIfAbsent(key, ignored -> nextId++);
        if (record) {
            rootSubtreeIds.add(id);
        }
        return id;
    }
}
